s.RegisterAction<IAxisInputGestureData, DeviceAxis>($"MotionProvider::{name}::Speed::Drive",
            s => s.WithLabel("Target axis").WithItemsSource(DeviceAxis.All),
            (data, axis) => UpdateProperty(axis, p => p.Speed = Math.Max(0.01, data.ApplyTo(p.Speed))));

s.RegisterAction<IAxisInputGestureData, DeviceAxis>($"MotionProvider::{name}::Minimum::Drive",
            s => s.WithLabel("Target axis").WithItemsSource(DeviceAxis.All),
            (data, axis) => UpdateProperty(axis, p => p.Minimum = MathUtils.Clamp01(data.ApplyTo(p.Minimum))));

s.RegisterAction<IAxisInputGestureData, DeviceAxis>($"MotionProvider::{name}::Maximum::Drive",
            s => s.WithLabel("Target axis").WithItemsSource(DeviceAxis.All),
            (data, axis) => UpdateProperty(axis, p => p.Maximum = MathUtils.Clamp01(data.ApplyTo(p.Maximum))));

s.RegisterAction<IAxisInputGestureData, DeviceAxis>("Axis::Value::Drive",
            s => s.WithLabel("Target axis").WithItemsSource(DeviceAxis.All),
            (data, axis) => SetAxisTransition(axis, data.ValueOrDelta, data.DeltaTime, offset: data.IsRelative));

s.RegisterAction<IAxisInputGestureData, DeviceAxis>("Axis::MotionProviderBlend::Drive",
            s => s.WithLabel("Target axis").WithItemsSource(DeviceAxis.All),
            (data, axis) => UpdateSettings(axis, s => s.MotionProviderBlend = MathUtils.Clamp01(data.ApplyTo(s.MotionProviderBlend))));

s.RegisterAction<string>($"{Name}::ServerBaseUri::Set", s => s.WithLabel("Endpoint").WithDescription("schema://ipOrHost:port"), serverBaseUri =>
        {
            if (Uri.TryCreate(serverBaseUri, UriKind.Absolute, out var uri))
                ServerBaseUri = uri;
        });

s.RegisterAction<string>($"{Name}::Device::SetByName", s => s.WithLabel("Name"), name => {
            var devcie = Devices.FirstOrDefault(p => string.Equals(p.Name, name, StringComparison.Ordinal));
            if (devcie == null)
                return;

            SelectDeviceById(devcie.Id);
        });

